import { ResultType, StepResponse } from '@txp-core/runtime';
import { Effect, put } from 'redux-saga/effects';
import {
    PaymentChargesTableAction,
    paymentTableSelectors
} from '@txp-core/payment-transactions-table';
import { CreditChargesPaymentTypes } from '@txp-core/payment-transactions-table/dist/paymentTableStateTypes';

function* outstandingTransactionsHandler(): Generator<Effect, StepResponse, string> {
    const creditTableLines = yield* select(paymentTableSelectors.getCredits);
    const totalOfChargesTable = yield* select(paymentTableSelectors.getTotalOfChargesTable);

    // Early return if no data to process
    if (!creditTableLines?.length || Number(totalOfChargesTable) <= 0) {
        return { result: ResultType.SUCCESS };
    }

    // Process credits with minimal copying
    let remainingBalance = Number(totalOfChargesTable);
    const updatedCredits: CreditChargesPaymentTypes[] = [];
    let needsUpdate = false;

    for (const credit of creditTableLines) {
        // Skip if no linked payment amount to process
        if (!credit.linkedPaymentAmount?.trim()) {
            updatedCredits.push(credit);
            continue;
        }

        // Calculate new amount
        const newAmount = remainingBalance >= credit.openBalance
            ? credit.openBalance.toString()
            : remainingBalance > 0
                ? remainingBalance.toString()
                : '';

        // Create new object only if changed
        if (credit.linkedPaymentAmount !== newAmount) {
            needsUpdate = true;
            updatedCredits.push({
                ...credit,
                linkedPaymentAmount: newAmount
            });

            // Update remaining balance
            remainingBalance -= newAmount ? Number(newAmount) : 0;
        } else {
            updatedCredits.push(credit);
        }
    }

    // Dispatch update only if changes were made
    if (needsUpdate) {
        yield put(PaymentChargesTableAction.fullCreditsTableUpdate(updatedCredits));
    }

    return { result: ResultType.SUCCESS };
}
```

