using System;
using System.Collections.Generic;
using Multicad;
using Multicad.DatabaseServices;
using Multicad.Geometry;
using Multicad.Runtime;

public static class TableEmbedder
{
    public static bool EmbedPrimitivesToTableCell(
        List<EntityGeometry> entities,
        McTable table,
        int rowIndex,
        int columnIndex)
    {
        // Input validation
        if (entities == null || entities.Count == 0) return false;
        if (table == null) return false;
        if (rowIndex < 0 || rowIndex >= table.RowsCount) return false;
        if (columnIndex < 0 || columnIndex >= table.ColumnsCount) return false;

        try
        {
            // Create compound entity
            using (var compound = new McCompound())
            {
                foreach (var entity in entities)
                {
                    if (entity != null)
                        compound.Entities.Add(entity.Clone() as EntityGeometry);
                }

                // Attempt direct embedding
                try
                {
                    table.SetCellContent(rowIndex, columnIndex, compound);
                    return true;
                }
                catch
                {
                    // Fallback to block reference
                    var block = new McBlock();
                    block.Entities.AddRange(compound.Entities);
                    Database.CurrentDatabase.BlockTable.Add(block);

                    var blockRef = new McBlockReference();
                    blockRef.BlockTableRecord = block.ObjectId;
                    Database.CurrentDatabase.ModelSpace.AddEntity(blockRef);

                    table.SetCellText(rowIndex, columnIndex, block.Name);
                    return true;
                }
            }
        }
        catch { return false; }
    }
}
```

